INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 105, 122601, 1, 0, 101, 110, 0, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 1.5, 160, 1, 1, 0.029);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (2, 111, 122401, 2, 0, 102, 105, 1, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 2.5, 120, 3, 0, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (3, 105, 122501, 3, 1, 103, 110, 0, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 2.5, 350, 2, 0, 0.017);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (4, 105, 107501, 4, 0, 104, 110, 1, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 1.5, 130, 3, 0, 0.016);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (5, 105, 107601, 5, 0, 105, 110, 0, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 2.5, 160, 1, 1, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (6, 103, 107801, 6, 1, 106, 120, 0, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 3.5, 255, 2, 0, 0.029);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (7, 103, 110601, 7, 0, 107, 120, 0, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 3.5, 160, 1, 1, 0.013);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (8, 103, 110401, 8, 1, 108, 110, 0, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 2.5, 350, 2, 0, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (9, 100, 110501, 9, 0, 109, 105, 1, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 1.5, 130, 3, 0, 0.012);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (10, 103, 115701, 10, 0, 110, 105, 0, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 2.5, 200, 1, 1, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (11, 103, 113601, 11, 1, 111, 105, 0, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 2.5, 350, 2, 0, 0.071);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (12, 103, 107901, 12, 0, 112, 120, 1, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 1.5, 130, 3, 0, 0.014);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (13, 105, 108001, 13, 0, 113, 110, 0, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 1.5, 200, 2, 1, 0.022);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (14, 108, 110301, 14, 0, 114, 110, 0, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 2.5, 160, 1, 1, 0.031);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (15, 105, 107701, 15, 0, 115, 110, 1, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 0.5, 130, 1, 0, 0.036);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (16, 95, 113101, 16, 1, 116, 110, 0, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 3.5, 350, 2, 0, 0.048);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (17, 105, 113301, 17, 0, 117, 105, 1, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 1.5, 130, 3, 0, 0.043);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (18, 95, 113201, 18, 0, 118, 105, 1, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 1.5, 130, 2, 0, 0.018);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (19, 108, 117001, 19, 0, 119, 110, 0, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 2.5, 160, 2, 1, 0.021);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (20, 105, 113501, 20, 1, 120, 110, 0, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 2.5, 255, 1, 0, 0.036);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (21, 105, 113401, 21, 1, 121, 105, 0, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 2.5, 350, 3, 0, 0.02);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (22, 105, 110101, 22, 0, 122, 110, 1, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 2.5, 130, 1, 0, 0.018);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (23, 111, 110001, 23, 0, 123, 105, 0, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 3.5, 160, 3, 1, 0.03);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (24, 103, 117201, 24, 0, 124, 110, 1, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 1.5, 130, 1, 0, 0.027);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (25, 108, 117301, 25, 0, 125, 105, 0, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 3.5, 160, 2, 1, 0.02);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (26, 105, 117401, 26, 1, 126, 110, 0, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 2.5, 350, 3, 0, 0.04);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (27, 105, 117101, 27, 1, 127, 110, 0, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 3.5, 350, 1, 0, 0.009);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (28, 105, 122901, 28, 1, 128, 120, 0, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 3.5, 255, 1, 0, 0.022);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (29, 105, 122801, 29, 0, 129, 110, 1, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 2.5, 130, 3, 0, 0.028);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (30, 108, 122701, 30, 0, 130, 105, 0, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 3.5, 130, 2, 1, 0.023);
